{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale each existing input embedding by 1 + 0.1 * min(c, 3), where c counts earlier occurrences of that item in the selected causal history. Padding contributes no feature. Apply this consistently during training and prediction through the model class already imported by the predictor writer, preserving embeddings, GRU topology, readout, loss and optimizer.",
      "edits": [
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        same_item = seq.unsqueeze(2).eq(seq.unsqueeze(1))\n        earlier_counts = same_item.tril(diagonal=-1).sum(dim=-1)\n        repeat_counts = earlier_counts.clamp_max(3) * seq.ne(0)\n        scale = 1.0 + 0.1 * repeat_counts.to(dtype=emb.dtype)\n        return self.dropout(emb * scale.unsqueeze(-1))\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.input_embeddings(seq)"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.input_embeddings(seq)"
        }
      ]
    }
  ],
  "change_summary": "Add deterministic causal repeat-count input scaling for all four category models. The generated predictor imports the updated model class, so inference uses identical feature construction without checkpoint changes."
}
